"""Check generated bytes against cantools and reject unsupported inputs."""
import importlib.util
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest

from codec_oracle import check_codec

ROOT = Path(__file__).resolve().parents[2]
SPEC = importlib.util.spec_from_file_location("dbc_codegen", ROOT / "tools/dbc_codegen.py")
codegen = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(codegen)


class CodegenTests(unittest.TestCase):
    def test_committed_output(self):
        subprocess.run([sys.executable, str(ROOT / "tools/dbc_codegen.py"), "--check"], check=True)

    def test_codec_against_cantools(self):
        check_codec(self, ROOT, codegen, ROOT / "dbc/automotive.dbc", ROOT / "dbc/can_policy.yaml")

    def test_reject_unsupported(self):
        dbc = (ROOT / "dbc/automotive.dbc").read_text()
        policy = (ROOT / "dbc/can_policy.yaml").read_text()
        cases = [
            (dbc.replace("SG_ LedRequest :", "SG_ LedRequest M :"), policy, "multiplexing"),
            (dbc.replace("0|32@1+", "0|33@1+").replace("39|12@0-", "47|12@0-"), policy, "1..32"),
            (dbc + "\nSIG_VALTYPE_ 2566848769 Counter : 1;\n", policy, "only integer signals"),
            (dbc.replace("(0.1,0)", "(-0.1,0)"), policy, "positive finite scale"),
            (dbc.replace("LedCommand: 4", "LedCommand: 9"), policy, "Classical CAN"),
            (dbc, policy.replace("timeout_ms: 60", "timeout_ms: 0"), "milliseconds"),
            (dbc, policy.replace("min_delay_ms: 15", "min_delay_ms: -1"), "milliseconds"),
            (dbc, policy.replace("timeout_ms: 60", "timeout_ms: 60\n    can_id: 288"), "expected exactly"),
            (dbc, policy.replace("timeout_ms: 60", "timeout_ms: 60\n    timeout_ms: 40"), "duplicate"),
            (dbc, policy.replace("mode: EVENT", "mode: UNKNOWN"), "unsupported TX mode"),
            (dbc, policy.replace("period_ms: 0", "period_ms: 10"), "EVENT requires"),
            (dbc, policy.replace("EventValue: TRIGGERED_ON_CHANGE", "EventValue: RANDOM"), "unsupported signal trigger"),
        ]
        with tempfile.TemporaryDirectory() as directory:
            db, settings = Path(directory) / "input.dbc", Path(directory) / "policy.yaml"
            for text, rules, message in cases:
                with self.subTest(message=message):
                    db.write_text(text)
                    settings.write_text(rules)
                    with self.assertRaisesRegex(ValueError, message):
                        codegen.generate(db, settings)

    def test_check_does_not_overwrite(self):
        with tempfile.TemporaryDirectory() as directory:
            command = [sys.executable, str(ROOT / "tools/dbc_codegen.py"), "--out", directory]
            subprocess.run(command, check=True, capture_output=True)
            target = Path(directory) / "can_cfg.h"
            target.write_text("stale\n")
            result = subprocess.run([*command, "--check"], capture_output=True, text=True)
            self.assertEqual(result.returncode, 1)
            self.assertIn("stale generated file", result.stderr)
            self.assertEqual(target.read_text(), "stale\n")


if __name__ == "__main__":
    unittest.main()
